92	export class JetEngine extends SceneObject<JetEngineTweenProps> {
93	  private static readonly DEFAULT_INTENSITY = 0.78;
94	  private static readonly DEFAULT_LENGTH = 2.4;
95	  private static readonly DEFAULT_NOZZLE_RADIUS = 0.028;
96	  private static readonly DEFAULT_NOZZLE_GAP = 2.2;
97	  private static readonly DEFAULT_INNER_RGB: RGB = [0.4, 0.75, 1.0];
98	  private static readonly DEFAULT_OUTER_RGB: RGB = [1.0, 0.92, 0.78];
99	  /** Outer shell length = core length × this (was 3.2 / 2.4 in author defaults). */
100	  private static readonly PARENT_LENGTH_RATIO = 3.2 / 2.4;
101	  private static readonly SIM_BURST_SPEED = 1.2;
102	  private static readonly SIM_BURST_AMP_MIN = 0.08;
103	  private static readonly SIM_BURST_AMP_MAX = 0.22;
104	  private static readonly SIM_SMOOTHING = 0.14;
105	  private static readonly TIP_MUL_INNER = 0.42;
106	  private static readonly TIP_MUL_OUTER = 0.88;
107	  /** Slightly above `Rocket` billboard flame (`renderOrder` 5). */
108	  private static readonly MESH_RENDER_ORDER = 6;
109	  private _options: Partial<JetEngineObjectOptions> = {};
110	  private _cfg: JetEngineResolvedConfig = JetEngine.resolveConfig({});
111	  private _sim: CombustionSim = new CombustionSim(
112	    this._cfg,
113	    JetEngine.easeOutExpo,
114	    JetEngine.easeOutCubic,
115	  );
116	
117	  private static sameRGB(a: RGB, b: RGB): boolean {
118	    return a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
119	  }
120	
121	  private static needsRebuild(
122	    prev: JetEngineResolvedConfig,
123	    next: JetEngineResolvedConfig,
124	  ): boolean {
125	    return (
126	      prev.nozzleRadius !== next.nozzleRadius ||
127	      prev.nozzleGap !== next.nozzleGap ||
128	      prev.baseLength !== next.baseLength ||
129	      prev.innerNoiseSpeed !== next.innerNoiseSpeed ||
130	      prev.parentNoiseSpeed !== next.parentNoiseSpeed ||
131	      prev.turbulence !== next.turbulence ||
132	      !JetEngine.sameRGB(prev.innerColor.top, next.innerColor.top) ||
133	      !JetEngine.sameRGB(prev.parentColor.top, next.parentColor.top)
134	    );
135	  }
136	
137	  private static darkenTip(c: RGB, mul: number): RGB {
138	    return [
139	      Math.min(1, c[0] * mul),
140	      Math.min(1, c[1] * mul),
141	      Math.min(1, c[2] * mul),
142	    ];
143	  }
144	
145	  private static glslVec3(c: RGB): string {
146	    return `vec3(${c[0].toFixed(4)},${c[1].toFixed(4)},${c[2].toFixed(4)})`;
147	  }
148	
149	  private static applyShaderTemplate(
150	    template: string,
151	    values: Record<string, string>,
152	  ): string {
153	    let out = template;
154	    for (const [key, value] of Object.entries(values)) {
155	      out = out.split(`__${key}__`).join(value);
156	    }
157	    return out;
158	  }
159	
160	  private static easeOutExpo(x: number): number {
161	    return x === 1 ? 1 : 1 - Math.pow(2, -10 * x);
162	  }
163	
164	  private static easeOutCubic(x: number): number {
165	    return 1 - Math.pow(1 - x, 3);
166	  }
167	
168	  private static resolveConfig(
169	    o: Partial<JetEngineObjectOptions>,
170	  ): JetEngineResolvedConfig {
171	    const intensity =
172	      typeof o.intensity === "number"
173	        ? Math.max(0, Math.min(1, o.intensity))
174	        : JetEngine.DEFAULT_INTENSITY;
175	    const gap =
176	      typeof o.nozzleGap === "number" && Number.isFinite(o.nozzleGap)
177	        ? o.nozzleGap
178	        : JetEngine.DEFAULT_NOZZLE_GAP;
179	    const length =
180	      typeof o.length === "number" && Number.isFinite(o.length)
181	        ? o.length
182	        : JetEngine.DEFAULT_LENGTH;
183	    const noise =
184	      typeof o.noise === "number" && Number.isFinite(o.noise)
185	        ? Math.max(0, o.noise)
186	        : 1;
187	    const bloom =
188	      typeof o.bloom === "number" && Number.isFinite(o.bloom)
189	        ? Math.max(0, o.bloom)
190	        : 1;
191	    const innerTop = o.innerColor ?? JetEngine.DEFAULT_INNER_RGB;
192	    const outerTop = o.outerColor ?? JetEngine.DEFAULT_OUTER_RGB;
193	    const nr =
194	      typeof o.nozzleRadius === "number" && Number.isFinite(o.nozzleRadius)
195	        ? o.nozzleRadius
196	        : JetEngine.DEFAULT_NOZZLE_RADIUS;
197	
198	    return {
199	      nozzleRadius: nr,
200	      nozzleGapX: gap,
201	      nozzleGapZ: gap,
202	      nozzleGap: gap,
203	      baseLength: length,
204	      parentLength: length * JetEngine.PARENT_LENGTH_RATIO,
205	      burstSpeed: JetEngine.SIM_BURST_SPEED,
206	      baseIdle: intensity,
207	      burstAmpMin: JetEngine.SIM_BURST_AMP_MIN,
208	      burstAmpMax: JetEngine.SIM_BURST_AMP_MAX,
209	      smoothing: JetEngine.SIM_SMOOTHING,
210	      innerNoiseSpeed: noise,
211	      parentNoiseSpeed: noise * 0.85,
212	      turbulence: noise,
213	      innerColor: {
214	        top: innerTop,
215	        tip: JetEngine.darkenTip(innerTop, JetEngine.TIP_MUL_INNER),
216	      },
217	      parentColor: {
218	        top: outerTop,
219	        tip: JetEngine.darkenTip(outerTop, JetEngine.TIP_MUL_OUTER),
220	      },
221	      innerBloom: bloom,
222	      parentBloom: bloom * 0.92,
223	    };
224	  }
225	
226	  private static innerVertGLSL(cfg: JetEngineResolvedConfig): string {
227	    return JetEngine.applyShaderTemplate(innerVertRaw as string, {
228	      NOISE_GLSL: noiseRaw as string,
229	      INNER_RS: (2.8 * cfg.innerNoiseSpeed).toFixed(3),
230	      INNER_LS: (2.2 * cfg.innerNoiseSpeed).toFixed(3),
231	      INNER_RT: (0.1 * cfg.turbulence).toFixed(4),
232	      INNER_LT: (0.22 * cfg.turbulence).toFixed(4),
233	    });
234	  }
235	
236	  private static innerFragGLSL(cfg: JetEngineResolvedConfig): string {
237	    const flash = JetEngine.glslVec3(
238	      cfg.innerColor.top.map((v) => Math.min(1, v + 0.2)) as RGB,
239	    );
240	    return JetEngine.applyShaderTemplate(innerFragRaw as string, {
241	      NOISE_GLSL: noiseRaw as string,
242	      INNER_FS1: (7.0 * cfg.innerNoiseSpeed).toFixed(3),
243	      INNER_FS2: (4.5 * cfg.innerNoiseSpeed).toFixed(3),
244	      INNER_C_TOP: JetEngine.glslVec3(cfg.innerColor.top),
245	      INNER_C_TIP: JetEngine.glslVec3(cfg.innerColor.tip),
246	      INNER_FLASH: flash,
247	    });
248	  }
249	
250	  private static parentVertGLSL(cfg: JetEngineResolvedConfig): string {
251	    return JetEngine.applyShaderTemplate(parentVertRaw as string, {
252	      NOISE_GLSL: noiseRaw as string,
253	      PARENT_RS: (2.4 * cfg.parentNoiseSpeed).toFixed(3),
254	      PARENT_LS: (1.8 * cfg.parentNoiseSpeed).toFixed(3),
255	      PARENT_RT: (0.18 * cfg.turbulence).toFixed(4),
256	      PARENT_LT: (0.3 * cfg.turbulence).toFixed(4),
257	    });
258	  }
259	
260	  private static parentFragGLSL(cfg: JetEngineResolvedConfig): string {
261	    return JetEngine.applyShaderTemplate(parentFragRaw as string, {
262	      NOISE_GLSL: noiseRaw as string,
263	      PARENT_FS1: (1.2 * cfg.parentNoiseSpeed).toFixed(3),
264	      PARENT_FS2: (0.7 * cfg.parentNoiseSpeed).toFixed(3),
265	      PARENT_C_TOP: JetEngine.glslVec3(cfg.parentColor.top),
266	      PARENT_C_TIP: JetEngine.glslVec3(cfg.parentColor.tip),
267	    });
268	  }
269	  private static readonly FRUSTUM_CULL_RADIUS = 1.5;
270	  private _inner: JetEngineRecord[] = [];
271	  private _parent: JetEngineRecord | null = null;
272	  private _innerGeo: THREE.BufferGeometry | null = null;
273	  private _built = false;
274	  private _intensity = JetEngine.DEFAULT_INTENSITY;
275	  private _frustum = new THREE.Frustum();
276	  private _projScreenMatrix = new THREE.Matrix4();
277	  private _frustumSphere = new THREE.Sphere();
278	
279	  setOptions(props: Partial<JetEngineObjectOptions> | undefined): this {
280	    if (props != null) this._options = { ...this._options, ...props };
281	    return this;
282	  }
283	
284	  override getAnimationTarget(): THREE.Object3D | null {
285	    return this.getTimelineRoot();
286	  }
287	
288	  override getTweenApplyMode(): "mergeAndSync" {
289	    return "mergeAndSync";
290	  }
291	
292	  protected override getOptions(): Record<string, unknown> {
293	    return this._options;
294	  }
295	
296	  protected override applyVisibility(visible: boolean): void {
297	    const root = this.getTimelineRoot();
298	    if (!root) return;
299	    root.visible = visible;
300	  }
301	
302	  protected override syncFromOptions(): void {
303	    const nextCfg = JetEngine.resolveConfig(this._options);
304	    this._intensity = Math.max(0, Math.min(1, nextCfg.baseIdle));
305	    const shouldRebuild =
306	      this._built && JetEngine.needsRebuild(this._cfg, nextCfg);
307	    this._cfg = nextCfg;
308	    this._sim.applyConfig(this._cfg);
309	    if (shouldRebuild) this._build();
310	  }
311	
312	  override runObject(): void {
313	    const ctx = this._context;
314	    if (!ctx?.scene) return;
315	
316	    const root = this.ensureTimelineRoot("jetEngineRoot");
317	    if (!root) return;
318	    this._cfg = JetEngine.resolveConfig(this._options);
319	    this._intensity = Math.max(0, Math.min(1, this._cfg.baseIdle));
320	    this._sim.applyConfig(this._cfg);
321	    this._build();
322	
323	    const attachTo = this._options.attachTo;
324	    const offset = this._options.offset ?? { x: 0, y: 0, z: 0 };
325	    const p = this._options.position ?? { x: 0, y: 0, z: 0 };
326	    const r = this._options.rotation ?? { x: 0, y: 0, z: 0 };
327	    const s = this._options.scale ?? { x: 1, y: 1, z: 1 };
328	
329	    if (attachTo && typeof ctx.getObject === "function") {
330	      const target = ctx.getObject(attachTo);
331	      if (target instanceof THREE.Object3D) {
332	        target.add(root);
333	        root.position.set(offset.x ?? 0, offset.y ?? 0, offset.z ?? 0);
334	      } else {
335	        root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
336	      }
337	    } else {
338	      root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
339	    }
340	
341	    Helpers.applyRotationDeg(root, r);
342	    root.scale.set(s.x ?? 1, s.y ?? 1, s.z ?? 1);
343	    root.traverse((child) => {
344	      child.layers.set(THREE_LAYER_ROCKET);
345	    });
346	    this._built = true;
347	  }
348	
349	  override runUpdate(deltaTime: number): void {
350	    if (!this._built) return;
351	    const root = this.getTimelineRoot();
352	    if (!root?.visible) return;
353	    const camera = this._context?.camera as THREE.PerspectiveCamera | undefined;
354	    if (!camera) return;
355	
356	    this._projScreenMatrix.multiplyMatrices(
357	      camera.projectionMatrix,
358	      camera.matrixWorldInverse,
359	    );
360	    this._frustum.setFromProjectionMatrix(this._projScreenMatrix);
361	    root.getWorldPosition(this._frustumSphere.center);
362	    this._frustumSphere.radius = JetEngine.FRUSTUM_CULL_RADIUS;
363	    if (!this._frustum.intersectsSphere(this._frustumSphere)) return;
364	
365	    const { flameLen, throttle, elapsed } = this._sim.update(deltaTime);
366	    const flameLenScaled = flameLen * this._intensity;
367	    const throttleScaled = throttle * this._intensity;
368	    const camQ = camera.quaternion;
369	    const innerBloomScale =
370	      this._cfg.innerBloom * throttleScaled * (0.8 + flameLenScaled * 0.5);
371	    for (const eng of this._inner) {
372	      eng.group.scale.y = this._cfg.baseLength * flameLenScaled;
373	      eng.mat.uniforms.uTime.value = elapsed;
374	      eng.mat.uniforms.uFlameLen.value = flameLenScaled;
375	      eng.mat.uniforms.uThrottle.value = throttleScaled;
376	      for (const b of eng.blooms) {
377	        b.mesh.quaternion.copy(camQ);
378	        b.mat.uniforms.uTime.value = elapsed;
379	        b.mat.uniforms.uIntensity.value = b.baseIntensity * innerBloomScale;
380	      }
381	    }
382	
383	    const parent = this._parent;
384	    if (!parent) return;
385	    parent.group.scale.y = this._cfg.parentLength * flameLenScaled;
386	    parent.mat.uniforms.uTime.value = elapsed;
387	    parent.mat.uniforms.uFlameLen.value = flameLenScaled;
388	    parent.mat.uniforms.uThrottle.value = throttleScaled;
389	    const parentBloomScale =
390	      this._cfg.parentBloom * throttleScaled * (0.7 + flameLenScaled * 0.5);
391	    for (const b of parent.blooms) {
392	      b.mesh.quaternion.copy(camQ);
393	      b.mat.uniforms.uTime.value = elapsed;
394	      b.mat.uniforms.uIntensity.value = b.baseIntensity * parentBloomScale;
395	    }
396	  }
397	
398	  override dispose(): void {
399	    this.releaseShaders(this.getShaderOwnerId());
400	    this._teardown();
401	    this._inner = [];
402	    this._parent = null;
403	    this._built = false;
404	    super.dispose();
405	  }
406	
407	  private _build(): void {
408	    const root = this.getTimelineRoot();
409	    if (!root) return;
410	    const shaderOwnerId = this.getShaderOwnerId();
411	    this.releaseShaders(shaderOwnerId);
412	    this._teardown();
413	    const cfg = this._cfg;
414	    const nr = cfg.nozzleRadius;
415	    const gridStepX = nr * Math.max(0.2, cfg.nozzleGapX);
416	    const gridStepZ = nr * Math.max(0.2, cfg.nozzleGapZ);
417	    const tipY = -(cfg.baseLength * 0.85);
418	    const parentR = Math.max(gridStepX, gridStepZ) * 1.9 + nr;
419	    const innerVert = JetEngine.innerVertGLSL(cfg);
420	    const innerFrag = JetEngine.innerFragGLSL(cfg);
421	    const parentVert = JetEngine.parentVertGLSL(cfg);
422	    const parentFrag = JetEngine.parentFragGLSL(cfg);
423	
424	    const layout: ReadonlyArray<readonly [number, number]> = [
425	      [-1, 2],
426	      [0, 2],
427	      [1, 2],
428	      [-0.5, 1],
429	      [0.5, 1],
430	      [-1, 0],
431	      [0, 0],
432	      [1, 0],
433	      [-0.5, -1],
434	      [0.5, -1],
435	      [-1, -2],
436	      [0, -2],
437	      [1, -2],
438	    ];
439	
440	    layout.forEach(([gx, gz], i) => {
441	      const pos = new THREE.Vector3(gx * gridStepX, 0, gz * gridStepZ);
442	      const isCenter = gx === 0 && gz === 0;
443	      if (!this._innerGeo) {
444	        this._innerGeo = new THREE.CylinderGeometry(0.004, nr, 1.0, 16, 12, true);
445	      }
446	      const geo = this._innerGeo;
447	      const mat = new THREE.ShaderMaterial({
448	        uniforms: {
449	          uTime: { value: 0 },
450	          uFlameLen: { value: 1 },
451	          uThrottle: { value: 1 },
452	          uSeed: { value: i * 2.71828 + 0.5 },
453	        },
454	        vertexShader: innerVert,
455	        fragmentShader: innerFrag,
456	        transparent: true,
457	        side: THREE.DoubleSide,
458	        depthWrite: false,
459	        blending: THREE.AdditiveBlending,
460	      });
461	      this.registerShader({
462	        key: this.createShaderKey(`inner.${i}`),
463	        ownerId: shaderOwnerId,
464	        material: mat,
465	        autoResolution: false,
466	      });
467	      const mesh = new THREE.Mesh(geo, mat);
468	      mesh.rotation.x = Math.PI;
469	      mesh.position.y = -0.5;
470	      mesh.layers.set(THREE_LAYER_ROCKET);
471	      mesh.renderOrder = JetEngine.MESH_RENDER_ORDER;
472	      const group = new THREE.Group();
473	      group.add(mesh);
474	      group.position.copy(pos);
475	      if (!isCenter) {
476	        const dir = new THREE.Vector3(0, tipY, 0).sub(pos).normalize();
477	        group.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir);
478	      }
479	      root.add(group);
480	      const blooms = this._buildBlooms(group, [
481	        {
482	          color: [0.3, 0.6, 1.0],
483	          radius: 6.0,
484	          size: nr * 5,
485	          baseI: 0.55,
486	          y: -0.05,
487	        },
488	        {
489	          color: [0.15, 0.4, 1.0],
490	          radius: 2.5,
491	          size: nr * 10,
492	          baseI: 0.35,
493	          y: -0.35,
494	        },
495	      ]);
496	      if (isCenter) {
497	        blooms.push(
498	          ...this._buildBlooms(group, [
499	            {
500	              color: cfg.innerColor.top,
501	              radius: 6.8,
502	              size: nr * 10.5,
503	              baseI: 0.42,
504	              y: 0.04,
505	            },
506	          ]),
507	        );
508	      }
509	      this._inner.push({ group, mat, blooms });
510	    });
511	
512	    const pGeo = new THREE.CylinderGeometry(0.01, parentR, 1.0, 32, 20, true);
513	    const pMat = new THREE.ShaderMaterial({
514	      uniforms: {
515	        uTime: { value: 0 },
516	        uFlameLen: { value: 1 },
517	        uThrottle: { value: 1 },
518	        uSeed: { value: 99.9 },
519	      },
520	      vertexShader: parentVert,
521	      fragmentShader: parentFrag,
522	      transparent: true,
523	      side: THREE.DoubleSide,
524	      depthWrite: false,
525	      blending: THREE.AdditiveBlending,
526	    });
527	    this.registerShader({
528	      key: this.createShaderKey("parent"),
529	      ownerId: shaderOwnerId,
530	      material: pMat,
531	      autoResolution: false,
532	    });
533	    const pMesh = new THREE.Mesh(pGeo, pMat);
534	    pMesh.rotation.x = Math.PI;
535	    pMesh.position.y = -0.5;
536	    pMesh.layers.set(THREE_LAYER_ROCKET);
537	    pMesh.renderOrder = JetEngine.MESH_RENDER_ORDER;
538	    const pGroup = new THREE.Group();
539	    pGroup.add(pMesh);
540	    root.add(pGroup);
541	    const pBlooms = this._buildBlooms(pGroup, [
542	      {
543	        color: [1.0, 0.95, 0.85],
544	        radius: 5.0,
545	        size: parentR * 4.5,
546	        baseI: 0.22,
547	        y: -0.05,
548	      },
549	      {
550	        color: [0.9, 0.95, 1.0],
551	        radius: 2.0,
552	        size: parentR * 7.0,
553	        baseI: 0.14,
554	        y: -0.4,
555	      },
556	    ]);
557	    this._parent = { group: pGroup, mat: pMat, blooms: pBlooms };
558	  }
559	
560	  private _teardown(): void {
561	    this._innerGeo?.dispose();
