468	      this._modelBounds.getCenter(this._modelBoundsCenter);
469	      out.set(
470	        this._modelBoundsCenter.x + x,
471	        this._modelBounds.min.y + y,
472	        this._modelBoundsCenter.z + z,
473	      );
474	      return out;
475	    }
476	
477	    anchor.getWorldPosition(this._anchorLocalPosition);
478	    model.worldToLocal(this._anchorLocalPosition);
479	    out.set(
480	      this._anchorLocalPosition.x + x,
481	      this._anchorLocalPosition.y + y,
482	      this._anchorLocalPosition.z + z,
483	    );
484	    return out;
485	  }
