35	vec3 hsv2rgb(vec3 c) {
36	  vec3 rgb = clamp(
37	    abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0,
38	    0.0,
39	    1.0
40	  );
41	  rgb = rgb * rgb * (3.0 - 2.0 * rgb);
42	  return c.z * mix(vec3(1.0), rgb, c.y);
43	}
44	
45	vec2 hash(vec2 p) {
46	  p = vec2(
47	    dot(p, vec2(127.1, 311.7)),
48	    dot(p, vec2(269.5, 183.3))
49	  );
50	  return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
51	}
