53	float noise(in vec2 p) {
54	  const float K1 = 0.366025404;
55	  const float K2 = 0.211324865;
56	
57	  vec2 cell = floor(p + (p.x + p.y) * K1);
58	  vec2 a = p - cell + (cell.x + cell.y) * K2;
59	  vec2 offset = (a.x > a.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
60	  vec2 b = a - offset + K2;
61	  vec2 c = a - 1.0 + 2.0 * K2;
62	
63	  vec3 h = max(0.5 - vec3(dot(a, a), dot(b, b), dot(c, c)), 0.0);
64	  vec3 grad = vec3(
65	    dot(a, hash(cell + 0.0)),
66	    dot(b, hash(cell + offset)),
67	    dot(c, hash(cell + 1.0))
68	  );
69	
70	  vec3 n = h * h * h * h * grad;
71	  return dot(n, vec3(70.0));
72	}
73	
74	float fbm(vec2 uv) {
75	  float value;
76	  mat2 rotScale = mat2(1.6, 1.2, -1.2, 1.6);
77	
78	  value = 0.5000 * noise(uv);
79	  uv = rotScale * uv;
80	  value += 0.2500 * noise(uv);
81	  uv = rotScale * uv;
82	  value += 0.1250 * noise(uv);
83	  uv = rotScale * uv;
84	  value += 0.0625 * noise(uv);
85	
86	  return 0.5 + 0.5 * value;
87	}
