89	vec2 toFlameUV(vec2 uv) {
90	  vec2 center = vec2(FLAME_CENTER_X, FLAME_CENTER_Y);
91	  vec2 scale = vec2(FLAME_SCALE_X, FLAME_SCALE_Y);
92	  return (uv - center) / scale;
93	}
94	
95	float getFlameNoise(vec2 flameUV) {
96	  float strength = FLAME_STRENGTH * uWaveStrength;
97	  float timeOffset = max(3.0, 1.25 * strength) * iTime * (uFlameSpeed / 3.0);
98	  float largeScale = fbm(strength * flameUV - vec2(0.0, timeOffset));
99	  float smallScale = fbm(
100	    strength * 2.5 * flameUV - vec2(0.0, timeOffset * 1.5)
101	  );
102	  return mix(largeScale, smallScale, TURBULENCE_MIX);
103	}
104	
105	float getFlameShape(vec2 flameUV, float noiseValue) {
106	  return 1.0 - 16.0 * pow(
107	    max(
108	      0.0,
109	      length(
110	        flameUV * vec2(
111	          FLAME_BASE_WIDTH + flameUV.y * FLAME_TAPER,
112	          FLAME_VERT_STRETCH
113	        )
114	      ) - noiseValue * FLAME_NOISE_DISTORTION * uWaveStrength * max(0.0, flameUV.y + 0.25)
115	    ),
116	    FLAME_EDGE_SOFTNESS
117	  );
118	}
119	
120	vec3 getFlameColor(float intensity, float tempMod) {
121	  vec3 col = vec3(
122	    1.5 * intensity,
123	    1.5 * pow(intensity, 3.0),
124	    pow(intensity, 6.0)
125	  );
126	
127	  float temp = FLAME_TEMPERATURE + tempMod;
128	  if (temp != 1.0) {
129	    col *= temp;
130	    col = mix(col, vec3(1.0), clamp(temp - 1.0, 0.0, 1.0));
131	  }
132	
133	  if (FLAME_SATURATION != 1.0) {
134	    float gray = dot(col, vec3(0.299, 0.587, 0.114));
135	    col = mix(vec3(gray), col, FLAME_SATURATION);
136	  }
137	
138	  if (FLAME_HUE != 0.0) {
139	    float maxc = max(col.r, max(col.g, col.b));
140	    float minc = min(col.r, min(col.g, col.b));
141	    float delta = maxc - minc;
142	    float h = 0.0;
143	    if (delta > 0.00001) {
144	      if (maxc == col.r) h = mod((col.g - col.b) / delta, 6.0);
145	      else if (maxc == col.g) h = (col.b - col.r) / delta + 2.0;
146	      else h = (col.r - col.g) / delta + 4.0;
147	      h /= 6.0;
148	    }
149	    float s = (maxc <= 0.0) ? 0.0 : delta / maxc;
150	    float v = maxc;
151	    h = fract(h + FLAME_HUE);
152	    col = hsv2rgb(vec3(h, s, v));
153	  }
154	
155	  return col;
156	}
157	
158	void mainImage(out vec4 fragColor, in vec2 fragCoord) {
159	  vec2 uv = fragCoord.xy / iResolution.xy;
160	  uv.y = 1.0 - uv.y;
161	
162	  float sway = ASYMMETRY_STRENGTH * uWaveStrength *
163	    noise(vec2(iTime * ASYMMETRY_SPEED * uFlameSpeed, uv.y * 2.0));
164	  vec2 flameUV = toFlameUV(uv + vec2(sway, 0.0));
165	  float noiseValue = getFlameNoise(flameUV);
166	  float shapeMask = getFlameShape(flameUV, noiseValue);
167	  float flicker = 1.0 + FLICKER_STRENGTH * noise(vec2(iTime * FLICKER_SPEED, 0.0));
168	  float tempMod = TEMP_MOD_STRENGTH * noise(vec2(iTime * TEMP_MOD_SPEED, 5.0));
169	  float flameIntensity =
170	    noiseValue * shapeMask * (1.5 - pow(FLAME_FADE_MULT * uv.y, FLAME_FADE_POW));
171	  flameIntensity = clamp(flameIntensity * flicker, 0.0, 1.0);
172	
173	  vec3 flameColor = getFlameColor(flameIntensity, tempMod);
174	  float alpha = shapeMask * (1.0 - pow(uv.y, 3.0));
175	
176	  if (SMOKE_STRENGTH > 0.0) {
177	    float smokeMask = smoothstep(SMOKE_HEIGHT, SMOKE_HEIGHT + 0.2, uv.y);
178	    vec3 smokeColor = vec3(0.2);
179	    flameColor = mix(flameColor, smokeColor, smokeMask * SMOKE_STRENGTH);
180	    alpha = mix(alpha, 0.0, smokeMask * SMOKE_STRENGTH);
181	  }
182	
183	  fragColor = vec4(flameColor, clamp(alpha * uOpacity, 0.0, 1.0));
184	}
185	
186	void main() {
187	  vec4 color;
188	  vec2 fragCoord = vec2(vUv.x * iResolution.x, vUv.y * iResolution.y);
189	  mainImage(color, fragCoord);
190	  gl_FragColor = color;
191	}
